with ranked as (select * from accounts qualify row_number() over (partition by status order by balance, id) = 1) select status, case when balance >= 72000 then 'LARGE' else 'SMALL' end as balance_tier, count(*) filter (where status = 'FROZEN') as frozen_rows, count(*) as cnt, sort_array(collect_set(status)) as status_list from ranked group by 1, 2 having frozen_rows > 1 order by frozen_rows desc nulls last;
